commands.command:
set -eu
install -d -m 755 /etc/nginx/http.d
if [ -f /etc/nginx/http.d/default.conf ]; then mv /etc/nginx/http.d/default.conf /etc/nginx/http.d/default.conf.disabled; fi
cat > /etc/nginx/http.d/secure-8443.conf <<'ANTRIEB_NGINX_EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols       TLSv1.2 TLSv1.3;

    location = / {
        default_type text/plain;
        return 200 "secure-os-comparison-ready\n";
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX_EOF
chmod 644 /etc/nginx/http.d/secure-8443.conf
nginx -t
